                            rs.getObject("round_date", LocalDate.class).toString(),
                            rs.getObject("due_by", LocalDate.class).toString(), until,
                            ClaimStatus.OPEN.name().equals(status) && until != null && until.isAfter(asOf),
                            0, null, null, false);
